-- LOT 06 - Conteneurs ID 60 a 66
-- Intermediaire: ne pas importer seul; sera assemble dans le SQL final.

START TRANSACTION;

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio con servizi igienici, dimensioni 6,00 x 2,40 m e altezza 2,70 m.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto con pannelli sandwich isolati da 7,5 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Struttura autoportante e stabile in acciaio saldato\n\nFINESTRE E PORTA\n- Due finestre a battente/basculanti con doppi vetri e due tapparelle\n- Porta esterna in acciaio Hörmann\n\nDOTAZIONI\n- Impianto elettrico completo conforme alle direttive CE, prese da 230 V e due plafoniere LED\n- Radiatore elettrico a parete da 2.000 W\n- Pavimento isolato con pannelli OSB e finitura laminata, robusta e facile da pulire\n- Occhielli per il sollevamento con gru e guide inferiori per carrello elevatore\n\nLeasing o noleggio con opzione di acquisto a partire da 147 € al mese. Possiamo realizzare dimensioni e colori diversi secondo le specifiche del cliente. Il prezzo indicato comprende l’IVA.\n\nPer lo scarico occorre predisporre attrezzatura adeguata, ad esempio un carrello elevatore o una pala gommata con forche. Condizioni e costi di consegna sono confermati nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin with sanitary facilities, measuring 6.00 x 2.40 m and 2.70 m high.\n\nSTRUCTURE AND INSULATION\n- Walls and roof with 7.5 cm insulated sandwich panels\n- Thermally broken profiles to reduce energy loss\n- Self-supporting, stable welded steel structure\n\nWINDOWS AND DOOR\n- Two double-glazed tilt-and-turn windows with two roller shutters\n- Hörmann external steel door\n\nEQUIPMENT\n- Complete CE-compliant electrical installation, 230 V sockets and two LED ceiling lights\n- 2,000 W wall-mounted electric heater\n- Insulated OSB floor with a durable, easy-to-clean laminate finish\n- Crane lifting eyes and lower forklift guides\n\nLeasing or rental with purchase option from EUR 147 per month. Other sizes and colours can be made to customer specifications. The stated price includes VAT.\n\nSuitable unloading equipment must be provided, such as a forklift or a wheeled loader with forks. Delivery terms and costs are confirmed in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau avec sanitaires, dimensions 6,00 x 2,40 m et hauteur de 2,70 m.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 7,5 cm\n- Profils à rupture de pont thermique pour réduire les pertes d’énergie\n- Structure autoportante et stable en acier soudé\n\nFENÊTRES ET PORTE\n- Deux fenêtres oscillo-battantes à double vitrage et deux volets roulants\n- Porte extérieure en acier Hörmann\n\nÉQUIPEMENTS\n- Installation électrique complète conforme CE, prises 230 V et deux plafonniers LED\n- Radiateur électrique mural de 2 000 W\n- Plancher isolé en OSB avec finition stratifiée résistante et facile à nettoyer\n- Anneaux de levage pour grue et guides inférieurs pour chariot élévateur\n\nLeasing ou location avec option d’achat à partir de 147 € par mois. D’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Le prix indiqué inclut la TVA.\n\nUn équipement adapté doit être prévu pour le déchargement, par exemple un chariot élévateur ou une chargeuse sur pneus équipée de fourches. Les modalités et frais de livraison sont confirmés dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina con instalaciones sanitarias, de 6,00 x 2,40 m y 2,70 m de altura.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo con paneles sándwich aislados de 7,5 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Estructura autoportante y estable de acero soldado\n\nVENTANAS Y PUERTA\n- Dos ventanas oscilobatientes con doble acristalamiento y dos persianas\n- Puerta exterior de acero Hörmann\n\nEQUIPAMIENTO\n- Instalación eléctrica completa conforme a CE, enchufes de 230 V y dos plafones LED\n- Radiador eléctrico mural de 2.000 W\n- Suelo aislado de OSB con acabado laminado resistente y fácil de limpiar\n- Argollas para grúa y guías inferiores para carretilla elevadora\n\nLeasing o alquiler con opción de compra desde 147 € al mes. Se pueden fabricar otras dimensiones y colores según las especificaciones del cliente. El precio indicado incluye IVA.\n\nPara la descarga debe disponerse de equipo adecuado, como una carretilla elevadora o una pala cargadora con horquillas. Las condiciones y los costes de entrega se confirman en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine mit Sanitäreinrichtung, Masse 6,00 x 2,40 m, Höhe 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 7,5 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND TÜR\n- Zwei Drehkippfenster mit Doppelverglasung und zwei Rollläden\n- Äussere Stahltür von Hörmann\n\nAUSSTATTUNG\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und zwei LED-Deckenleuchten\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit robuster, pflegeleichter Laminatoberfläche\n- Kranösen und untere Staplerführungen\n\nLeasing oder Miete mit Kaufoption ab 147 € pro Monat. Andere Masse und Farben sind nach Kundenspezifikation möglich. Der angegebene Preis enthält die Mehrwertsteuer.\n\nFür das Entladen ist geeignete Ausrüstung bereitzustellen, zum Beispiel ein Gabelstapler oder ein Radlader mit Gabeln. Lieferbedingungen und -kosten werden im Angebot bestätigt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit met sanitaire voorzieningen, 6,00 x 2,40 m en 2,70 m hoog.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak met geïsoleerde sandwichpanelen van 7,5 cm\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Zelfdragende, stabiele gelaste staalconstructie\n\nRAMEN EN DEUR\n- Twee draai-kiepramen met dubbele beglazing en twee rolluiken\n- Externe stalen Hörmann-deur\n\nUITRUSTING\n- Volledige CE-conforme elektrische installatie, 230V-stopcontacten en twee led-plafondlampen\n- Elektrische wandradiator van 2.000 W\n- Geïsoleerde OSB-vloer met sterke, gemakkelijk te reinigen laminaatafwerking\n- Hijsogen voor een kraan en onderste heftruckgeleiders\n\nLease of huur met koopoptie vanaf € 147 per maand. Andere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. De vermelde prijs is inclusief btw.\n\nVoor het lossen moet geschikte apparatuur beschikbaar zijn, zoals een heftruck of wiellader met vorken. De leveringsvoorwaarden en -kosten worden in de offerte bevestigd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimistomoduuli, jossa on saniteettitilat. Mitat 6,00 x 2,40 m, korkeus 2,70 m.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 7,5 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Itsekantava ja vakaa hitsattu teräsrunko\n\nIKKUNAT JA OVI\n- Kaksi kaksilasista avattavaa ja kallistettavaa ikkunaa sekä kaksi rullaverhoa\n- Hörmannin ulkoinen teräsovi\n\nVARUSTEET\n- Täydellinen CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja kaksi LED-kattovalaisinta\n- 2 000 W:n sähköinen seinälämmitin\n- Eristetty OSB-lattia kestävällä ja helposti puhdistettavalla laminaattipinnalla\n- Nostokorvakkeet nosturille ja alaosan trukkiohjaimet\n\nLeasing tai vuokraus osto-optiolla alkaen 147 €/kk. Muita kokoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Ilmoitettu hinta sisältää arvonlisäveron.\n\nPurkamista varten on järjestettävä sopiva kalusto, kuten trukki tai haarukoilla varustettu pyöräkuormaaja. Toimitusehdot ja -kulut vahvistetaan tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine mit Sanitäreinrichtung, Masse 6,00 x 2,40 m, Höhe 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 7,5 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND TÜR\n- Zwei Drehkippfenster mit Doppelverglasung und zwei Rollläden\n- Äussere Stahltür von Hörmann\n\nAUSSTATTUNG\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und zwei LED-Deckenleuchten\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit robuster, pflegeleichter Laminatoberfläche\n- Kranösen und untere Staplerführungen\n\nLeasing oder Miete mit Kaufoption ab 147 € pro Monat. Andere Masse und Farben sind nach Kundenspezifikation möglich. Der angegebene Preis enthält die Mehrwertsteuer.\n\nFür das Entladen ist geeignete Ausrüstung bereitzustellen, zum Beispiel ein Gabelstapler oder ein Radlader mit Gabeln. Lieferbedingungen und -kosten werden im Angebot bestätigt.')
WHERE `id` = 60 AND `reference` = 'CABINA DA UFFICIO RIPARO DA GIARDINO / MAGAZZINO';

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio di 3,00 x 2,00 m, altezza 2,70 m.\n\nSTRUTTURA E DOTAZIONI\n- Struttura in acciaio 100 x 50 x 4 mm\n- Pareti in pannelli sandwich da 75 mm\n- Pavimento in OSB su telaio in acciaio 100 x 100 mm\n- Una finestra in PVC con apertura a ribalta\n- Quattro occhielli superiori per scarico con gru e attacchi inferiori per carrelli elevatori\n- Porta d’ingresso Hörmann\n- Prese elettriche, quadro elettrico, lampada fluorescente e radiatore elettrico a parete\n- Possibilità di realizzare dimensioni e colori diversi secondo le specifiche del cliente\n\nLe spese di trasporto possono variare. Contattateci prima dell’acquisto per chiarire eventuali domande. Condizioni e costi di consegna sono confermati nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin measuring 3.00 x 2.00 m and 2.70 m high.\n\nSTRUCTURE AND EQUIPMENT\n- Steel structure: 100 x 50 x 4 mm\n- Walls made of 75 mm sandwich panels\n- OSB floor on a 100 x 100 mm steel frame\n- One PVC tilt window\n- Four upper lifting eyes for crane unloading and lower forklift fittings\n- Hörmann entrance door\n- Electrical sockets, electrical panel, fluorescent light and wall-mounted electric heater\n- Other sizes and colours can be made to customer specifications\n\nTransport costs may vary. Contact us before purchase to discuss any questions. Delivery terms and costs are confirmed in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau de 3,00 x 2,00 m et de 2,70 m de hauteur.\n\nSTRUCTURE ET ÉQUIPEMENTS\n- Structure en acier de 100 x 50 x 4 mm\n- Murs en panneaux sandwich de 75 mm\n- Plancher en OSB sur cadre en acier de 100 x 100 mm\n- Une fenêtre PVC à soufflet\n- Quatre anneaux supérieurs pour déchargement par grue et fixations inférieures pour chariot élévateur\n- Porte d’entrée Hörmann\n- Prises électriques, tableau électrique, luminaire fluorescent et radiateur électrique mural\n- D’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client\n\nLes frais de transport peuvent varier. Contactez-nous avant l’achat pour toute question. Les modalités et coûts de livraison sont confirmés dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina de 3,00 x 2,00 m y 2,70 m de altura.\n\nESTRUCTURA Y EQUIPAMIENTO\n- Estructura de acero de 100 x 50 x 4 mm\n- Paredes de paneles sándwich de 75 mm\n- Suelo de OSB sobre bastidor de acero de 100 x 100 mm\n- Una ventana abatible de PVC\n- Cuatro argollas superiores para descarga con grúa y anclajes inferiores para carretilla elevadora\n- Puerta de entrada Hörmann\n- Enchufes, cuadro eléctrico, lámpara fluorescente y radiador eléctrico mural\n- Se pueden fabricar otras dimensiones y colores según las especificaciones del cliente\n\nLos costes de transporte pueden variar. Contacte con nosotros antes de la compra para resolver cualquier duda. Las condiciones y los costes de entrega se confirman en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine mit den Massen 3,00 x 2,00 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND AUSSTATTUNG\n- Stahlkonstruktion: 100 x 50 x 4 mm\n- Wände aus 75-mm-Sandwichpaneelen\n- OSB-Boden auf einem 100 x 100 mm starken Stahlrahmen\n- Ein kippbares PVC-Fenster\n- Vier obere Hebeösen zum Entladen mit einem Kran und untere Stapleraufnahmen\n- Eingangstür von Hörmann\n- Steckdosen, Elektrokasten, Leuchtstofflampe und elektrischer Wandheizkörper\n- Andere Masse und Farben nach Kundenspezifikation möglich\n\nDie Transportkosten können variieren. Kontaktieren Sie uns vor dem Kauf, um offene Fragen zu klären. Lieferbedingungen und -kosten werden im Angebot bestätigt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit van 3,00 x 2,00 m en 2,70 m hoog.\n\nCONSTRUCTIE EN UITRUSTING\n- Stalen constructie van 100 x 50 x 4 mm\n- Wanden van sandwichpanelen van 75 mm\n- OSB-vloer op een stalen frame van 100 x 100 mm\n- Eén kiepraam van PVC\n- Vier bovenste hijsogen voor lossen met een kraan en onderste bevestigingen voor een heftruck\n- Hörmann-toegangsdeur\n- Stopcontacten, elektriciteitskast, tl-lamp en elektrische wandradiator\n- Andere afmetingen en kleuren mogelijk volgens de specificaties van de klant\n\nTransportkosten kunnen variëren. Neem vóór aankoop contact met ons op om vragen te bespreken. De leveringsvoorwaarden en -kosten worden in de offerte bevestigd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimistomoduuli, mitat 3,00 x 2,00 m, korkeus 2,70 m.\n\nRAKENNE JA VARUSTEET\n- Teräsrunko: 100 x 50 x 4 mm\n- Seinät 75 mm:n sandwich-paneeleista\n- OSB-lattia 100 x 100 mm:n teräsrungon päällä\n- Yksi PVC-kippi-ikkuna\n- Neljä yläosan nostokorvaketta nosturipurkua varten ja alaosan trukkikiinnikkeet\n- Hörmann-sisäänkäyntiovi\n- Pistorasiat, sähkökeskus, loistevalaisin ja sähköinen seinälämmitin\n- Muita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan\n\nKuljetuskustannukset voivat vaihdella. Ota yhteyttä ennen ostoa, jos haluat selvittää kysymyksiä. Toimitusehdot ja -kulut vahvistetaan tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine mit den Massen 3,00 x 2,00 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND AUSSTATTUNG\n- Stahlkonstruktion: 100 x 50 x 4 mm\n- Wände aus 75-mm-Sandwichpaneelen\n- OSB-Boden auf einem 100 x 100 mm starken Stahlrahmen\n- Ein kippbares PVC-Fenster\n- Vier obere Hebeösen zum Entladen mit einem Kran und untere Stapleraufnahmen\n- Eingangstür von Hörmann\n- Steckdosen, Elektrokasten, Leuchtstofflampe und elektrischer Wandheizkörper\n- Andere Masse und Farben nach Kundenspezifikation möglich\n\nDie Transportkosten können variieren. Kontaktieren Sie uns vor dem Kauf, um offene Fragen zu klären. Lieferbedingungen und -kosten werden im Angebot bestätigt.')
WHERE `id` = 61 AND `reference` = 'CABINA UFFICIO DI GUARDIA';

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio di 4,00 x 2,40 m, altezza 2,70 m.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto con pannelli sandwich isolati da 8 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Struttura autoportante e stabile in acciaio saldato\n\nFINESTRE E DOTAZIONI\n- Due finestre a battente/basculanti con doppi vetri\n- Porta esterna in acciaio Hörmann\n- Impianto elettrico conforme alle direttive CE, prese da 230 V e una lampada da soffitto\n- Radiatore elettrico a parete da 2.000 W\n- Pavimento isolato in OSB con rivestimento in PVC robusto e facile da pulire\n- Occhielli per il sollevamento con gru e guida inferiore per carrello elevatore\n\nPossiamo realizzare altre dimensioni e colori secondo le specifiche del cliente. Per lo scarico è necessario predisporre attrezzatura adeguata. Modalità e costi di consegna sono definiti nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin measuring 4.00 x 2.40 m and 2.70 m high.\n\nSTRUCTURE AND INSULATION\n- Walls and roof with 8 cm insulated sandwich panels\n- Thermally broken profiles to reduce energy loss\n- Self-supporting, stable welded steel structure\n\nWINDOWS AND EQUIPMENT\n- Two double-glazed tilt-and-turn windows\n- Hörmann external steel door\n- CE-compliant electrical installation, 230 V sockets and one ceiling light\n- 2,000 W wall-mounted electric heater\n- Insulated OSB floor with durable, easy-to-clean PVC covering\n- Crane lifting eyes and lower forklift guide\n\nOther sizes and colours can be made to customer specifications. Suitable equipment must be provided for unloading. Delivery terms and costs are set out in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau de 4,00 x 2,40 m et de 2,70 m de hauteur.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 8 cm\n- Profils à rupture de pont thermique pour limiter les pertes d’énergie\n- Structure autoportante et stable en acier soudé\n\nFENÊTRES ET ÉQUIPEMENTS\n- Deux fenêtres oscillo-battantes à double vitrage\n- Porte extérieure en acier Hörmann\n- Installation électrique conforme CE, prises 230 V et plafonnier\n- Radiateur électrique mural de 2 000 W\n- Plancher isolé en OSB avec revêtement PVC résistant et facile à nettoyer\n- Anneaux de levage pour grue et guide inférieur pour chariot élévateur\n\nD’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Un équipement adapté doit être prévu pour le déchargement. Les modalités et coûts de livraison sont définis dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina de 4,00 x 2,40 m y 2,70 m de altura.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo con paneles sándwich aislados de 8 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Estructura autoportante y estable de acero soldado\n\nVENTANAS Y EQUIPAMIENTO\n- Dos ventanas oscilobatientes con doble acristalamiento\n- Puerta exterior de acero Hörmann\n- Instalación eléctrica conforme a CE, enchufes de 230 V y una lámpara de techo\n- Radiador eléctrico mural de 2.000 W\n- Suelo aislado de OSB con revestimiento de PVC resistente y fácil de limpiar\n- Argollas para grúa y guía inferior para carretilla elevadora\n\nSe pueden fabricar otras dimensiones y colores según las especificaciones del cliente. Para la descarga debe disponerse de equipo adecuado. Las condiciones y los costes de entrega se indican en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine mit den Massen 4,00 x 2,40 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 8 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und eine Deckenleuchte\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit strapazierfähigem, pflegeleichtem PVC-Belag\n- Kranösen und untere Staplerführung\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Für das Entladen ist geeignete Ausrüstung bereitzustellen. Lieferbedingungen und -kosten werden im Angebot festgelegt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit van 4,00 x 2,40 m en 2,70 m hoog.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak met geïsoleerde sandwichpanelen van 8 cm\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Zelfdragende, stabiele gelaste staalconstructie\n\nRAMEN EN UITRUSTING\n- Twee draai-kiepramen met dubbele beglazing\n- Externe stalen Hörmann-deur\n- CE-conforme elektrische installatie, 230V-stopcontacten en één plafondlamp\n- Elektrische wandradiator van 2.000 W\n- Geïsoleerde OSB-vloer met sterke, gemakkelijk te reinigen PVC-bedekking\n- Hijsogen voor een kraan en onderste heftruckgeleider\n\nAndere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. Voor het lossen moet geschikte apparatuur beschikbaar zijn. De leveringsvoorwaarden en -kosten staan in de offerte.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimistomoduuli, mitat 4,00 x 2,40 m, korkeus 2,70 m.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 8 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Itsekantava ja vakaa hitsattu teräsrunko\n\nIKKUNAT JA VARUSTEET\n- Kaksi kaksilasista avattavaa ja kallistettavaa ikkunaa\n- Hörmannin ulkoinen teräsovi\n- CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja kattovalaisin\n- 2 000 W:n sähköinen seinälämmitin\n- Eristetty OSB-lattia kestävällä ja helposti puhdistettavalla PVC-pinnalla\n- Nostokorvakkeet nosturille ja alaosan trukkiohjain\n\nMuita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Purkamiseen on järjestettävä sopiva kalusto. Toimitusehdot ja -kulut määritellään tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine mit den Massen 4,00 x 2,40 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 8 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und eine Deckenleuchte\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit strapazierfähigem, pflegeleichtem PVC-Belag\n- Kranösen und untere Staplerführung\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Für das Entladen ist geeignete Ausrüstung bereitzustellen. Lieferbedingungen und -kosten werden im Angebot festgelegt.')
WHERE `id` = 62 AND `reference` = 'CABINA DA UFFICIO RIPARO DA GIARDINO';

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio di 2,00 x 2,00 m.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto con pannelli sandwich isolati da 8 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Porta esterna in acciaio zincato Hörmann\n\nFINESTRE E DOTAZIONI\n- Tre finestre con doppi vetri\n- Impianto elettrico conforme alle direttive CE, prese da 230 V e lampada da soffitto\n- Radiatore elettrico a parete\n- Pavimento isolato in OSB con finitura in PVC robusta e facile da pulire\n\nPer lo scarico è necessario predisporre attrezzatura adeguata. Sono disponibili altre dimensioni e colori a magazzino; è possibile anche richiedere una realizzazione secondo le proprie specifiche. Modalità e costi di consegna sono definiti nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin measuring 2.00 x 2.00 m.\n\nSTRUCTURE AND INSULATION\n- Walls and roof with 8 cm insulated sandwich panels\n- Thermally broken profiles to reduce energy loss\n- Hörmann external galvanised steel door\n\nWINDOWS AND EQUIPMENT\n- Three double-glazed windows\n- CE-compliant electrical installation, 230 V sockets and ceiling light\n- Wall-mounted electric heater\n- Insulated OSB floor with durable, easy-to-clean PVC finish\n\nSuitable equipment must be provided for unloading. Other sizes and colours are available from stock; custom production to specification can also be requested. Delivery terms and costs are set out in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau de 2,00 x 2,00 m.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 8 cm\n- Profils à rupture de pont thermique pour limiter les pertes d’énergie\n- Porte extérieure en acier galvanisé Hörmann\n\nFENÊTRES ET ÉQUIPEMENTS\n- Trois fenêtres à double vitrage\n- Installation électrique conforme CE, prises 230 V et plafonnier\n- Radiateur électrique mural\n- Plancher isolé en OSB avec finition PVC résistante et facile à nettoyer\n\nUn équipement adapté doit être prévu pour le déchargement. D’autres dimensions et couleurs sont disponibles en stock ; une fabrication sur mesure peut également être demandée. Les modalités et coûts de livraison sont définis dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina de 2,00 x 2,00 m.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo con paneles sándwich aislados de 8 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Puerta exterior de acero galvanizado Hörmann\n\nVENTANAS Y EQUIPAMIENTO\n- Tres ventanas con doble acristalamiento\n- Instalación eléctrica conforme a CE, enchufes de 230 V y lámpara de techo\n- Radiador eléctrico mural\n- Suelo aislado de OSB con acabado de PVC resistente y fácil de limpiar\n\nPara la descarga debe disponerse de equipo adecuado. Hay otras dimensiones y colores disponibles en stock; también se puede solicitar fabricación según especificaciones. Las condiciones y los costes de entrega se indican en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine mit den Massen 2,00 x 2,00 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 8 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Äussere verzinkte Stahltür von Hörmann\n\nFENSTER UND AUSSTATTUNG\n- Drei Fenster mit Doppelverglasung\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Elektrischer Wandheizkörper\n- Isolierter OSB-Boden mit strapazierfähiger, pflegeleichter PVC-Oberfläche\n\nFür das Entladen ist geeignete Ausrüstung bereitzustellen. Andere Masse und Farben sind ab Lager verfügbar; eine Fertigung nach Kundenspezifikation kann ebenfalls angefragt werden. Lieferbedingungen und -kosten werden im Angebot festgelegt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit van 2,00 x 2,00 m.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak met geïsoleerde sandwichpanelen van 8 cm\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Externe verzinkte stalen Hörmann-deur\n\nRAMEN EN UITRUSTING\n- Drie ramen met dubbele beglazing\n- CE-conforme elektrische installatie, 230V-stopcontacten en plafondlamp\n- Elektrische wandradiator\n- Geïsoleerde OSB-vloer met sterke, gemakkelijk te reinigen PVC-afwerking\n\nVoor het lossen moet geschikte apparatuur beschikbaar zijn. Andere afmetingen en kleuren zijn uit voorraad leverbaar; productie volgens specificaties kan ook worden aangevraagd. De leveringsvoorwaarden en -kosten staan in de offerte.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimistomoduuli, mitat 2,00 x 2,00 m.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 8 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Hörmannin ulkoinen sinkitty teräsovi\n\nIKKUNAT JA VARUSTEET\n- Kolme kaksilasista ikkunaa\n- CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja kattovalaisin\n- Sähköinen seinälämmitin\n- Eristetty OSB-lattia kestävällä ja helposti puhdistettavalla PVC-pinnalla\n\nPurkamiseen on järjestettävä sopiva kalusto. Muita kokoja ja värejä on varastossa; myös valmistusta asiakkaan eritelmien mukaan voidaan pyytää. Toimitusehdot ja -kulut määritellään tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine mit den Massen 2,00 x 2,00 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 8 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Äussere verzinkte Stahltür von Hörmann\n\nFENSTER UND AUSSTATTUNG\n- Drei Fenster mit Doppelverglasung\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Elektrischer Wandheizkörper\n- Isolierter OSB-Boden mit strapazierfähiger, pflegeleichter PVC-Oberfläche\n\nFür das Entladen ist geeignete Ausrüstung bereitzustellen. Andere Masse und Farben sind ab Lager verfügbar; eine Fertigung nach Kundenspezifikation kann ebenfalls angefragt werden. Lieferbedingungen und -kosten werden im Angebot festgelegt.')
WHERE `id` = 63 AND `reference` = 'CABINA DA UFFICIO PROTEZIONE DI GUARDIA / SERVIZIO';

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio di 4,00 x 2,40 m, altezza 2,70 m.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto con pannelli sandwich isolati da 7,5 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Struttura autoportante e stabile in acciaio saldato\n\nFINESTRE E DOTAZIONI\n- Due finestre a battente/basculanti con doppi vetri\n- Porta esterna in acciaio Hörmann\n- Impianto elettrico completo conforme alle direttive CE, prese da 230 V e lampada da soffitto\n- Radiatore elettrico a parete da 2.000 W\n- Pavimento isolato in OSB con finitura laminata robusta e facile da pulire\n- Occhielli per il sollevamento con gru e guida inferiore per carrello elevatore\n\nPossiamo realizzare altre dimensioni e colori secondo le specifiche del cliente. Per lo scarico è necessario predisporre attrezzatura adeguata. Il prezzo indicato comprende l’IVA. Modalità e costi di consegna sono confermati nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin measuring 4.00 x 2.40 m and 2.70 m high.\n\nSTRUCTURE AND INSULATION\n- Walls and roof with 7.5 cm insulated sandwich panels\n- Thermally broken profiles to reduce energy loss\n- Self-supporting, stable welded steel structure\n\nWINDOWS AND EQUIPMENT\n- Two double-glazed tilt-and-turn windows\n- Hörmann external steel door\n- Complete CE-compliant electrical installation, 230 V sockets and ceiling light\n- 2,000 W wall-mounted electric heater\n- Insulated OSB floor with a durable, easy-to-clean laminate finish\n- Crane lifting eyes and lower forklift guide\n\nOther sizes and colours can be made to customer specifications. Suitable equipment must be provided for unloading. The stated price includes VAT. Delivery terms and costs are confirmed in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau de 4,00 x 2,40 m et de 2,70 m de hauteur.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 7,5 cm\n- Profils à rupture de pont thermique pour limiter les pertes d’énergie\n- Structure autoportante et stable en acier soudé\n\nFENÊTRES ET ÉQUIPEMENTS\n- Deux fenêtres oscillo-battantes à double vitrage\n- Porte extérieure en acier Hörmann\n- Installation électrique complète conforme CE, prises 230 V et plafonnier\n- Radiateur électrique mural de 2 000 W\n- Plancher isolé en OSB avec finition stratifiée résistante et facile à nettoyer\n- Anneaux de levage pour grue et guide inférieur pour chariot élévateur\n\nD’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Un équipement adapté doit être prévu pour le déchargement. Le prix indiqué inclut la TVA. Les modalités et coûts de livraison sont confirmés dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina de 4,00 x 2,40 m y 2,70 m de altura.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo con paneles sándwich aislados de 7,5 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Estructura autoportante y estable de acero soldado\n\nVENTANAS Y EQUIPAMIENTO\n- Dos ventanas oscilobatientes con doble acristalamiento\n- Puerta exterior de acero Hörmann\n- Instalación eléctrica completa conforme a CE, enchufes de 230 V y lámpara de techo\n- Radiador eléctrico mural de 2.000 W\n- Suelo aislado de OSB con acabado laminado resistente y fácil de limpiar\n- Argollas para grúa y guía inferior para carretilla elevadora\n\nSe pueden fabricar otras dimensiones y colores según las especificaciones del cliente. Para la descarga debe disponerse de equipo adecuado. El precio indicado incluye IVA. Las condiciones y los costes de entrega se confirman en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine mit den Massen 4,00 x 2,40 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 7,5 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit robuster, pflegeleichter Laminatoberfläche\n- Kranösen und untere Staplerführung\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Für das Entladen ist geeignete Ausrüstung bereitzustellen. Der angegebene Preis enthält die Mehrwertsteuer. Lieferbedingungen und -kosten werden im Angebot bestätigt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit van 4,00 x 2,40 m en 2,70 m hoog.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak met geïsoleerde sandwichpanelen van 7,5 cm\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Zelfdragende, stabiele gelaste staalconstructie\n\nRAMEN EN UITRUSTING\n- Twee draai-kiepramen met dubbele beglazing\n- Externe stalen Hörmann-deur\n- Volledige CE-conforme elektrische installatie, 230V-stopcontacten en plafondlamp\n- Elektrische wandradiator van 2.000 W\n- Geïsoleerde OSB-vloer met sterke, gemakkelijk te reinigen laminaatafwerking\n- Hijsogen voor een kraan en onderste heftruckgeleider\n\nAndere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. Voor het lossen moet geschikte apparatuur beschikbaar zijn. De vermelde prijs is inclusief btw. De leveringsvoorwaarden en -kosten worden in de offerte bevestigd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimistomoduuli, mitat 4,00 x 2,40 m, korkeus 2,70 m.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 7,5 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Itsekantava ja vakaa hitsattu teräsrunko\n\nIKKUNAT JA VARUSTEET\n- Kaksi kaksilasista avattavaa ja kallistettavaa ikkunaa\n- Hörmannin ulkoinen teräsovi\n- Täydellinen CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja kattovalaisin\n- 2 000 W:n sähköinen seinälämmitin\n- Eristetty OSB-lattia kestävällä ja helposti puhdistettavalla laminaattipinnalla\n- Nostokorvakkeet nosturille ja alaosan trukkiohjain\n\nMuita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Purkamiseen on järjestettävä sopiva kalusto. Ilmoitettu hinta sisältää arvonlisäveron. Toimitusehdot ja -kulut vahvistetaan tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine mit den Massen 4,00 x 2,40 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 7,5 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit robuster, pflegeleichter Laminatoberfläche\n- Kranösen und untere Staplerführung\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Für das Entladen ist geeignete Ausrüstung bereitzustellen. Der angegebene Preis enthält die Mehrwertsteuer. Lieferbedingungen und -kosten werden im Angebot bestätigt.')
WHERE `id` = 64 AND `reference` = 'CABINA PER UFFICIO RESIDENZIALE';

UPDATE `conteneurs`
SET `description` = 'Nuova cabina ufficio in magazzino, disponibile immediatamente. Dimensioni: 6,00 x 2,43 m. Il prezzo indicato comprende l’IVA al 19%. La cabina è fornita completa e pronta all’uso; lo scarico non è incluso.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto con pannelli sandwich isolati da 8 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Struttura autoportante in acciaio saldato, non imbullonata\n\nFINESTRE E DOTAZIONI\n- Finestre a battente/basculanti con doppi vetri\n- Porta esterna in acciaio Hörmann\n- Impianto elettrico conforme alle direttive CE, prese da 230 V e lampada da soffitto\n- Radiatore elettrico a parete da 2.000 W\n- Pavimento isolato in OSB con finitura in PVC resistente e facile da pulire\n\nPer lo scarico è necessario predisporre gru, carrello elevatore o pala gommata con forche. Possiamo realizzare altre dimensioni e colori secondo le specifiche del cliente. Leasing o noleggio con opzione di acquisto a partire da 147 € al mese. Per i costi e le condizioni di consegna, contattateci: saranno confermati nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'New office cabin in stock and available immediately. Dimensions: 6.00 x 2.43 m. The stated price includes 19% VAT. The cabin is supplied complete and ready for use; unloading is not included.\n\nSTRUCTURE AND INSULATION\n- Walls and roof with 8 cm insulated sandwich panels\n- Thermally broken profiles to reduce energy loss\n- Self-supporting welded steel structure, not bolted\n\nWINDOWS AND EQUIPMENT\n- Double-glazed tilt-and-turn windows\n- Hörmann external steel door\n- CE-compliant electrical installation, 230 V sockets and ceiling light\n- 2,000 W wall-mounted electric heater\n- Insulated OSB floor with durable, easy-to-clean PVC finish\n\nA crane, forklift or wheeled loader with forks must be arranged for unloading. Other sizes and colours can be made to customer specifications. Leasing or rental with purchase option from EUR 147 per month. Contact us for delivery costs and terms; these will be confirmed in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau neuve en stock, disponible immédiatement. Dimensions : 6,00 x 2,43 m. Le prix indiqué comprend une TVA de 19 %. La cabine est fournie complète et prête à l’emploi ; le déchargement n’est pas inclus.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 8 cm\n- Profils à rupture de pont thermique pour limiter les pertes d’énergie\n- Structure autoportante en acier soudé, non boulonnée\n\nFENÊTRES ET ÉQUIPEMENTS\n- Fenêtres oscillo-battantes à double vitrage\n- Porte extérieure en acier Hörmann\n- Installation électrique conforme CE, prises 230 V et plafonnier\n- Radiateur électrique mural de 2 000 W\n- Plancher isolé en OSB avec finition PVC résistante et facile à nettoyer\n\nUne grue, un chariot élévateur ou une chargeuse sur pneus équipée de fourches doit être prévu pour le déchargement. D’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Leasing ou location avec option d’achat à partir de 147 € par mois. Contactez-nous pour les modalités et frais de livraison ; ils seront confirmés dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina nueva en stock y disponible de inmediato. Dimensiones: 6,00 x 2,43 m. El precio indicado incluye un 19 % de IVA. Se suministra completa y lista para usar; la descarga no está incluida.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo con paneles sándwich aislados de 8 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Estructura autoportante de acero soldado, no atornillada\n\nVENTANAS Y EQUIPAMIENTO\n- Ventanas oscilobatientes con doble acristalamiento\n- Puerta exterior de acero Hörmann\n- Instalación eléctrica conforme a CE, enchufes de 230 V y lámpara de techo\n- Radiador eléctrico mural de 2.000 W\n- Suelo aislado de OSB con acabado de PVC resistente y fácil de limpiar\n\nPara la descarga debe disponerse de grúa, carretilla elevadora o pala cargadora con horquillas. Se pueden fabricar otras dimensiones y colores según las especificaciones del cliente. Leasing o alquiler con opción de compra desde 147 € al mes. Contacte con nosotros para conocer las condiciones y costes de entrega; se confirmarán en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Neue Bürokabine ab Lager, sofort verfügbar. Masse: 6,00 x 2,43 m. Der angegebene Preis enthält 19 % Mehrwertsteuer. Die Kabine wird vollständig und einsatzbereit geliefert; das Entladen ist nicht inbegriffen.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 8 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, geschweisste Stahlkonstruktion, nicht verschraubt\n\nFENSTER UND AUSSTATTUNG\n- Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit strapazierfähiger, pflegeleichter PVC-Oberfläche\n\nZum Entladen muss ein Kran, Gabelstapler oder Radlader mit Gabeln bereitgestellt werden. Andere Masse und Farben sind nach Kundenspezifikation möglich. Leasing oder Miete mit Kaufoption ab 147 € pro Monat. Lieferbedingungen und -kosten werden auf Anfrage im Angebot bestätigt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Nieuwe kantoorunit op voorraad en direct beschikbaar. Afmetingen: 6,00 x 2,43 m. De vermelde prijs is inclusief 19% btw. De unit wordt compleet en gebruiksklaar geleverd; lossen is niet inbegrepen.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak met geïsoleerde sandwichpanelen van 8 cm\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Zelfdragende gelaste staalconstructie, niet geschroefd\n\nRAMEN EN UITRUSTING\n- Draai-kiepramen met dubbele beglazing\n- Externe stalen Hörmann-deur\n- CE-conforme elektrische installatie, 230V-stopcontacten en plafondlamp\n- Elektrische wandradiator van 2.000 W\n- Geïsoleerde OSB-vloer met sterke, gemakkelijk te reinigen PVC-afwerking\n\nVoor het lossen moet een kraan, heftruck of wiellader met vorken beschikbaar zijn. Andere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. Lease of huur met koopoptie vanaf € 147 per maand. Neem contact met ons op over leveringsvoorwaarden en -kosten; deze worden in de offerte bevestigd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Uusi toimistomoduuli varastossa ja heti saatavilla. Mitat: 6,00 x 2,43 m. Ilmoitettu hinta sisältää 19 % arvonlisäveron. Moduuli toimitetaan kokonaisena ja käyttövalmiina; purku ei sisälly toimitukseen.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 8 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Itsekantava hitsattu teräsrunko, ei pulttiliitoksia\n\nIKKUNAT JA VARUSTEET\n- Kaksilasinen avattava ja kallistettava ikkuna\n- Hörmannin ulkoinen teräsovi\n- CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja kattovalaisin\n- 2 000 W:n sähköinen seinälämmitin\n- Eristetty OSB-lattia kestävällä ja helposti puhdistettavalla PVC-pinnalla\n\nPurkamista varten on järjestettävä nosturi, trukki tai haarukoilla varustettu pyöräkuormaaja. Muita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Leasing tai vuokraus osto-optiolla alkaen 147 €/kk. Toimitusehdot ja -kulut vahvistetaan tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Neue Bürokabine ab Lager, sofort verfügbar. Masse: 6,00 x 2,43 m. Der angegebene Preis enthält 19 % Mehrwertsteuer. Die Kabine wird vollständig und einsatzbereit geliefert; das Entladen ist nicht inbegriffen.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 8 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, geschweisste Stahlkonstruktion, nicht verschraubt\n\nFENSTER UND AUSSTATTUNG\n- Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Elektrischer Wandheizkörper mit 2.000 W\n- Isolierter OSB-Boden mit strapazierfähiger, pflegeleichter PVC-Oberfläche\n\nZum Entladen muss ein Kran, Gabelstapler oder Radlader mit Gabeln bereitgestellt werden. Andere Masse und Farben sind nach Kundenspezifikation möglich. Leasing oder Miete mit Kaufoption ab 147 € pro Monat. Lieferbedingungen und -kosten werden auf Anfrage im Angebot bestätigt.')
WHERE `id` = 65 AND `reference` = 'CABINA PER UFFICIO RESIDENZIALE CHIAVI IN MANO';

UPDATE `conteneurs`
SET `description` = 'Casetta da giardino o cabina ufficio con finitura effetto legno, dimensioni 5,00 x 2,50 m e altezza 2,70 m. Adatta come deposito, ufficio da giardino o spazio per hobby.\n\nCARATTERISTICHE\n- Pareti e tetto con pannelli sandwich isolati da 10 cm\n- Profili a taglio termico per una migliore efficienza energetica\n- Due finestre fisse da 90 x 190 cm\n- Impianto elettrico conforme alle direttive CE, con prese da 230 V\n- Lampada da soffitto e radiatore elettrico a parete\n- Pavimento robusto in PVC, facile da pulire e resistente alle intemperie\n- Pavimento e tetto isolati per l’utilizzo durante tutto l’anno\n- Opzione occhielli per gru per facilitare lo spostamento: 1.000 €',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Wood-effect garden cabin or office cabin, measuring 5.00 x 2.50 m and 2.70 m high. Suitable as a storage space, garden office or hobby room.\n\nFEATURES\n- Walls and roof with 10 cm insulated sandwich panels\n- Thermally broken profiles for improved energy efficiency\n- Two fixed windows measuring 90 x 190 cm\n- CE-compliant electrical installation with 230 V sockets\n- Ceiling light and wall-mounted electric heater\n- Durable, easy-to-clean, weather-resistant PVC floor\n- Insulated floor and roof for year-round use\n- Optional crane lifting eyes to facilitate handling: EUR 1,000'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabane de jardin ou cabine de bureau avec finition imitation bois, dimensions 5,00 x 2,50 m et hauteur de 2,70 m. Convient comme espace de rangement, bureau de jardin ou pièce de loisirs.\n\nCARACTÉRISTIQUES\n- Murs et toit en panneaux sandwich isolés de 10 cm\n- Profils à rupture de pont thermique pour une meilleure efficacité énergétique\n- Deux fenêtres fixes de 90 x 190 cm\n- Installation électrique conforme CE avec prises 230 V\n- Plafonnier et radiateur électrique mural\n- Sol en PVC résistant aux intempéries, durable et facile à nettoyer\n- Sol et toit isolés pour une utilisation toute l’année\n- Anneaux de levage pour grue en option afin de faciliter la manutention : 1 000 €'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Caseta de jardín o cabina de oficina con acabado efecto madera, de 5,00 x 2,50 m y 2,70 m de altura. Adecuada como almacén, oficina de jardín o espacio para aficiones.\n\nCARACTERÍSTICAS\n- Paredes y techo con paneles sándwich aislados de 10 cm\n- Perfiles con rotura de puente térmico para mejorar la eficiencia energética\n- Dos ventanas fijas de 90 x 190 cm\n- Instalación eléctrica conforme a CE con enchufes de 230 V\n- Lámpara de techo y radiador eléctrico mural\n- Suelo de PVC duradero, fácil de limpiar y resistente a la intemperie\n- Suelo y techo aislados para uso durante todo el año\n- Argollas para grúa opcionales para facilitar la manipulación: 1.000 €'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Gartenhaus oder Bürokabine in Holzoptik, Masse 5,00 x 2,50 m, Höhe 2,70 m. Geeignet als Lagerraum, Gartenbüro oder Hobbyraum.\n\nMERKMALE\n- Wände und Dach mit 10 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile für bessere Energieeffizienz\n- Zwei feststehende Fenster mit 90 x 190 cm\n- CE-konforme Elektroinstallation mit 230-V-Steckdosen\n- Deckenleuchte und elektrischer Wandheizkörper\n- Strapazierfähiger, pflegeleichter und witterungsbeständiger PVC-Boden\n- Isolierter Boden und isoliertes Dach für ganzjährige Nutzung\n- Optionale Kranösen zur einfacheren Handhabung: 1.000 €'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Tuinhuis of kantoorunit met houtlook, 5,00 x 2,50 m en 2,70 m hoog. Geschikt als opslagruimte, tuinkantoor of hobbyruimte.\n\nKENMERKEN\n- Wanden en dak met geïsoleerde sandwichpanelen van 10 cm\n- Thermisch onderbroken profielen voor betere energie-efficiëntie\n- Twee vaste ramen van 90 x 190 cm\n- CE-conforme elektrische installatie met 230V-stopcontacten\n- Plafondlamp en elektrische wandradiator\n- Duurzame, gemakkelijk te reinigen en weerbestendige PVC-vloer\n- Geïsoleerde vloer en dak voor gebruik het hele jaar door\n- Optionele hijsogen voor een kraan voor gemakkelijker verplaatsen: € 1.000'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Puukuosinen puutarhamökki tai toimistomoduuli, mitat 5,00 x 2,50 m, korkeus 2,70 m. Sopii varastoksi, puutarhatoimistoksi tai harrastetilaksi.\n\nOMINAISUUDET\n- Seinät ja katto 10 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit parantavat energiatehokkuutta\n- Kaksi kiinteää ikkunaa, 90 x 190 cm\n- CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat\n- Kattovalaisin ja sähköinen seinälämmitin\n- Kestävä, helposti puhdistettava ja säänkestävä PVC-lattia\n- Eristetty lattia ja katto ympärivuotiseen käyttöön\n- Valinnaiset nostokorvakkeet helpottamaan siirtoa: 1 000 €'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Gartenhaus oder Bürokabine in Holzoptik, Masse 5,00 x 2,50 m, Höhe 2,70 m. Geeignet als Lagerraum, Gartenbüro oder Hobbyraum.\n\nMERKMALE\n- Wände und Dach mit 10 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile für bessere Energieeffizienz\n- Zwei feststehende Fenster mit 90 x 190 cm\n- CE-konforme Elektroinstallation mit 230-V-Steckdosen\n- Deckenleuchte und elektrischer Wandheizkörper\n- Strapazierfähiger, pflegeleichter und witterungsbeständiger PVC-Boden\n- Isolierter Boden und isoliertes Dach für ganzjährige Nutzung\n- Optionale Kranösen zur einfacheren Handhabung: 1.000 €')
WHERE `id` = 66 AND `reference` = 'BUNGALOW';

COMMIT;
